            ind,
            elem_stride,
            counts,
            rank,
            compact,
            off,
            curs,
            rbuf,
            m,
            nnz,
            BP=1024,
            BM=1024,
            WRITE_CSR=use_csr,
            num_warps=_FUSED_PREP_WARPS,
