            col_sorted,
            val_sorted,
            b,
            outv,
            out_ind,
            compact,
            counts,
            off,
            n,
            total,
            stride_bk,
            stride_bn,
            nblk,
            ncomp,
            FP64=fp64,
            BP=_CBP,
            BN=_CBN,
            BI=_BI,
